std::priority_queue<TreeNode*, std::vector<TreeNode*>, std::function<bool(TreeNode*, TreeNode*)>> pq(
    [](TreeNode* a, TreeNode* b) { return a->freq > b->freq; });

for (int i = 0; i < size; ++i) {
    pq.push(new TreeNode(values[i], freqs[i]));
}

while (pq.size() > 1) {
    TreeNode* left = pq.top();
    pq.pop();
    TreeNode* right = pq.top();
    pq.pop();

    double combinedFreq = left->freq + right->freq;
    TreeNode* parent = new TreeNode(-1, combinedFreq);
    parent->left = left;
    parent->right = right;
    pq.push(parent);
}

return pq.empty() ? nullptr : pq.top();
// END_CODE

